package com.andye.warmod.rocket.client;import com.mojang.blaze3d.vertex.*;import net.minecraft.client.renderer.texture.OverlayTexture;public final class RocketTrailRenderer {private RocketTrailRenderer(){}public static void renderFlame(PoseStack.Pose p,VertexConsumer b,RocketProjectileRenderState s){float pulse=.85f+.35f*(.5f+.5f*(float)Math.sin(s.ageInTicks*.93+s.visualSeed*.0001));float base=-(float)s.payloadType.length()/2f;cross(p,b,base,base-.65f*pulse,.13f,255,150,35,225);cross(p,b,base-.02f,base-.42f*pulse,.075f,255,245,185,255);}public static void renderSmoke(PoseStack.Pose p,VertexConsumer b,RocketProjectileRenderState s){float base=-(float)s.payloadType.length()/2f;for(int i=0;i<10;i++){float y=base-.35f-i*.22f,size=.12f+i*.025f;double phase=s.visualSeed*.00001+i*1.7+s.ageInTicks*.13;float x=(float)Math.sin(phase)*.035f,z=(float)Math.cos(phase)*.035f;billboard(p,b,x,y,z,size,132,137,132,Math.max(18,130-i*11));}}private static void cross(PoseStack.Pose p,VertexConsumer b,float y1,float y2,float w,int r,int g,int bl,int a){quad(p,b,-w,y1,0,w,y1,0,w*.25f,y2,0,-w*.25f,y2,0,r,g,bl,a);quad(p,b,0,y1,-w,0,y1,w,0,y2,w*.25f,0,y2,-w*.25f,r,g,bl,a);}private static void billboard(PoseStack.Pose p,VertexConsumer b,float x,float y,float z,float s,int r,int g,int bl,int a){quad(p,b,x-s,y-s,z,x+s,y-s,z,x+s,y+s,z,x-s,y+s,z,r,g,bl,a);quad(p,b,x,y-s,z-s,x,y-s,z+s,x,y+s,z+s,x,y+s,z-s,r,g,bl,a);}private static void quad(PoseStack.Pose p,VertexConsumer b,float ax,float ay,float az,float bx,float by,float bz,float cx,float cy,float cz,float dx,float dy,float dz,int r,int g,int bl,int a){v(p,b,ax,ay,az,0,0,r,g,bl,a);v(p,b,bx,by,bz,1,0,r,g,bl,a);v(p,b,cx,cy,cz,1,1,r,g,bl,a);v(p,b,dx,dy,dz,0,1,r,g,bl,a);}private static void v(PoseStack.Pose p,VertexConsumer b,float x,float y,float z,float u,float v,int r,int g,int bl,int a){b.addVertex(p,x,y,z).setColor(r,g,bl,a).setUv(u,v).setOverlay(OverlayTexture.NO_OVERLAY).setLight(15728880).setNormal(p,0,1,0);}}